<?php

namespace App\Services\Signing\Delta;

/**
 * How a delta build's IPA is put together: byte ranges of the base IPA, of the pack and of the shared
 * core (delta-v2), plus generated bytes (local headers of segmented entries, the central directory).
 * Known before the first byte is sent, so Content-Length and Range work.
 */
final class ComposedPlan
{
    public const BASE = 0;

    public const PACK = 1;

    public const MEMORY = 2;

    public const CORE = 3;

    public function __construct(
        /** @var list<array{0: int, 1: int, 2: int}> [source, offset, length]; MEMORY offsets index $memory. */
        public readonly array $segments,
        /** Generated bytes: local headers of segmented entries, then the central directory and the end record. */
        public readonly string $memory,
        public readonly int $size,
        public readonly int $entries,
        public readonly int $packEntries,
        public readonly string $baseSha256,
        /** The pack manifest's version: 1 (delta-v1) or 2 (delta-v2). */
        public readonly int $version = 1,
        /** @var list<array{name: string, crc: int, size: int, segments: list<array{0: int, 1: int, 2: int}>}> kind-2 entries */
        public readonly array $segmented = [],
        /** The core the segmented entries read from, when any of them does. */
        public readonly ?string $coreSha256 = null,
    ) {}

    /**
     * Writes the bytes [start, end] of the composed IPA to the output.
     *
     * @param  callable(string): void  $write
     * @param  callable(): bool  $alive  false once the client has gone
     */
    public function stream(string $basePath, string $packPath, int $start, int $end, callable $write, callable $alive, ?string $corePath = null): void
    {
        $handles = [];
        try {
            $position = 0;
            foreach ($this->segments as [$source, $offset, $length]) {
                $segmentEnd = $position + $length - 1;
                if ($segmentEnd >= $start && $position <= $end) {
                    $from = max($start, $position) - $position;
                    $count = min($end, $segmentEnd) - $position - $from + 1;
                    if ($source === self::MEMORY) {
                        $write(substr($this->memory, $offset + $from, $count));
                    } else {
                        $this->copy($handles, $source, [$basePath, $packPath, $corePath], $offset + $from, $count, $write, $alive);
                    }
                }
                $position += $length;
                if ($position > $end || ! $alive()) {
                    break;
                }
            }
        } finally {
            foreach ($handles as $handle) {
                fclose($handle);
            }
        }
    }

    /**
     * Inflates every segmented entry from its chunks and checks that the stream is one valid raw
     * DEFLATE stream of exactly `size` bytes with CRC-32 `crc`, ending exactly at its last chunk.
     *
     * @throws DeltaException naming the first entry that does not match
     */
    public function checkSegmented(string $packPath, ?string $corePath): void
    {
        $handles = [];
        try {
            foreach ($this->segmented as $entry) {
                $inflate = inflate_init(ZLIB_ENCODING_RAW) ?: throw new DeltaException('Cannot start inflate.');
                $crc = hash_init('crc32b');
                $produced = 0;
                $consumed = 0;
                $total = array_sum(array_column($entry['segments'], 2));
                $feed = function (string $chunk) use ($inflate, $crc, &$produced, &$consumed, $entry) {
                    if (inflate_get_status($inflate) === ZLIB_STREAM_END) {
                        throw new DeltaException("{$entry['name']} has bytes after its final block.");
                    }
                    $out = @inflate_add($inflate, $chunk, ZLIB_SYNC_FLUSH);
                    if ($out === false) {
                        throw new DeltaException("{$entry['name']} is not a valid DEFLATE stream.");
                    }
                    $consumed += strlen($chunk);
                    $produced += strlen($out);
                    if ($produced > $entry['size']) {
                        throw new DeltaException("{$entry['name']} inflates to more than its size.");
                    }
                    hash_update($crc, $out);
                };
                foreach ($entry['segments'] as [$source, $offset, $length]) {
                    $this->copy($handles, $source, [null, $packPath, $corePath], $offset, $length, $feed, fn () => true);
                }
                // read_len counts input consumed so far: all of it, and the final block ended the stream.
                if (inflate_get_status($inflate) !== ZLIB_STREAM_END || inflate_get_read_len($inflate) !== $total) {
                    throw new DeltaException("{$entry['name']} does not end with its final block.");
                }
                if ($produced !== $entry['size']) {
                    throw new DeltaException("{$entry['name']} inflates to {$produced} bytes, not {$entry['size']}.");
                }
                if (hexdec(hash_final($crc)) !== $entry['crc']) {
                    throw new DeltaException("{$entry['name']} does not match its CRC-32.");
                }
            }
        } finally {
            foreach ($handles as $handle) {
                fclose($handle);
            }
        }
    }

    /**
     * @param  array<int, resource>  $handles  open files by source, kept across calls
     * @param  array{0: string|null, 1: string|null, 2: string|null}  $paths  base, pack, core
     * @param  callable(string): void  $write
     * @param  callable(): bool  $alive
     */
    private function copy(array &$handles, int $source, array $paths, int $offset, int $count, callable $write, callable $alive): void
    {
        $path = match ($source) {
            self::BASE => $paths[0],
            self::PACK => $paths[1],
            self::CORE => $paths[2],
            default => null,
        } ?? throw new DeltaException('A delta source is not available.');
        $handles[$source] ??= @fopen($path, 'rb') ?: throw new DeltaException('Cannot open a delta source.');
        fseek($handles[$source], $offset);
        while ($count > 0 && $alive()) {
            $chunk = fread($handles[$source], min(1024 * 1024, $count));
            if ($chunk === false || $chunk === '') {
                throw new DeltaException('A delta source ended early.');
            }
            $write($chunk);
            $count -= strlen($chunk);
        }
    }
}
